import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';
import { describe, expect, it } from 'vitest';

// Core frontend code must not import an addon's generated routes or actions. Those modules exist only while the
// addon is installed, and the build of a checkout without the addon fails on them. An addon's link goes through the
// addon's pages instead (provides.pages, with its url), read from the generated artefacts.

const repoRoot = process.cwd();
const jsRoot = join(repoRoot, 'resources/js');
// Generated by Wayfinder or by the addon generator. Not core code.
const GENERATED_TOP_LEVEL = new Set([
    'routes',
    'actions',
    'wayfinder',
    'generated',
]);

function addonSlugs(): string[] {
    const addonsRoot = join(repoRoot, 'addons');

    return readdirSync(addonsRoot).filter((name) => {
        try {
            return statSync(join(addonsRoot, name, 'addon.json')).isFile();
        } catch {
            return false;
        }
    });
}

function coreSourceFiles(dir: string = jsRoot): string[] {
    return readdirSync(dir).flatMap((name) => {
        const path = join(dir, name);

        if (dir === jsRoot && GENERATED_TOP_LEVEL.has(name)) {
            return [];
        }

        if (statSync(path).isDirectory()) {
            return coreSourceFiles(path);
        }

        return /\.(ts|tsx)$/.test(name) ? [path] : [];
    });
}

describe('core frontend does not import addon routes or actions', () => {
    it('finds no core file that imports an installed addon’s generated routes or actions', () => {
        // With no addons installed, the list is empty and the guard passes, which is correct.
        const slugs = addonSlugs();

        const violations: string[] = [];

        for (const file of coreSourceFiles()) {
            const lines = readFileSync(file, 'utf8').split('\n');

            lines.forEach((line, index) => {
                for (const slug of slugs) {
                    const escaped = slug.replace(
                        /[.*+?^${}()|[\]\\-]/g,
                        '\\$&',
                    );
                    const pattern = new RegExp(
                        `['"]@/(routes|actions|wayfinder)/${escaped}(['"/])`,
                    );

                    if (pattern.test(line)) {
                        violations.push(
                            `${relative(repoRoot, file)}:${index + 1} imports @/…/${slug}`,
                        );
                    }
                }
            });
        }

        expect(violations).toEqual([]);
    });
});
